#!/usr/bin/env node
/*
 * Inlines vendor/xlsx.mini.min.js into main.js between the BUNDLED_XLSX markers,
 * wrapped as a CommonJS factory that returns the XLSX object.
 *
 * Why: Obsidian's installer delivers only main.js / manifest.json / styles.css —
 * the vendor/ folder is NOT shipped, and require() against plugin paths is
 * unreliable in the runtime. Inlining guarantees XLSX export/import always works.
 * The lib is embedded as a function body (not a string + eval), so V8 lazily
 * compiles it only on first getXLSX() use and the store reviewer sees no eval.
 *
 * Run after updating vendor/xlsx.mini.min.js:
 *   node scripts/bundle-xlsx.js
 */
'use strict';
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const libPath = path.join(root, 'vendor', 'xlsx.mini.min.js');
const mainPath = path.join(root, 'main.js');

const BEGIN = '/* ===BEGIN BUNDLED_XLSX (generated by scripts/bundle-xlsx.js from vendor/xlsx.mini.min.js — do not edit by hand) === */';
const END = '/* ===END BUNDLED_XLSX=== */';

const lib = fs.readFileSync(libPath, 'utf8');
if (lib.includes(END)) throw new Error('vendor lib contains the END marker string — cannot inline safely');

const fn = [
  'function loadBundledXLSX() {',
  '  const module = { exports: {} };',
  '  const exports = module.exports;',
  '  (function (module, exports) {',
  lib,
  '  })(module, exports);',
  '  return module.exports;',
  '}',
].join('\n');

const main = fs.readFileSync(mainPath, 'utf8');
const begin = main.indexOf(BEGIN);
const end = main.indexOf(END);
if (begin < 0 || end < 0 || end < begin) {
  throw new Error('BUNDLED_XLSX markers not found in main.js');
}

const replacement = `${BEGIN}\n${fn}\n${END}`;
const next = main.slice(0, begin) + replacement + main.slice(end + END.length);
fs.writeFileSync(mainPath, next);
console.log(`Inlined vendor/xlsx.mini.min.js (${lib.length} bytes) into main.js.`);
